-- Suggested PostgreSQL schema. Each table matches a collection in src/data/seed.js,
-- and each function in src/services/api.js maps to one or more of these tables.
create table outlets (id text primary key, name text not null);
create table users (id text primary key, name text not null, email text unique not null, role text not null check (role in ('Admin','Cashier')), pin_hash text not null);
create table categories (id text primary key, name text unique not null);            -- only an Admin may insert/delete
create table products (id text primary key, sku text unique not null, name text not null, category_id text not null references categories, price numeric(10,2) not null, wholesale numeric(10,2), cost numeric(10,2) not null, color text, reorder_level int not null default 5);
create table stock_levels (product_id text references products on delete cascade, outlet_id text references outlets, qty int not null default 0 check (qty >= 0), primary key (product_id, outlet_id));
create table stock_transfers (id text primary key, t timestamptz not null default now(), product_id text references products, from_outlet text references outlets, to_outlet text references outlets, qty int not null check (qty > 0), user_id text references users);
create table customers (id text primary key, first_name text not null, last_name text not null, address text, phone text, email text, points int not null default 0, spent numeric(12,2) not null default 0, credit numeric(10,2) not null default 0);
create table register_sessions (id text primary key, outlet_id text references outlets, opened_at timestamptz not null, opened_by text references users, float numeric(10,2) not null default 0, closed_at timestamptz, closed_by text references users, counted numeric(10,2), expected numeric(10,2), variance numeric(10,2)); -- counted is optional
create table sales (id text primary key, number int unique not null, t timestamptz not null default now(), outlet_id text references outlets, cashier_id text references users, customer_id text references customers, kind text not null default 'sale' check (kind in ('sale','order')), order_id text, subtotal numeric(10,2), discount numeric(10,2), total numeric(10,2), tax numeric(10,2), deposit_applied numeric(10,2) not null default 0, pay_method text not null check (pay_method in ('Cash','Card','Amex','Store credit')), tendered numeric(10,2), change_given numeric(10,2), status text not null default 'completed' check (status in ('completed','refunded')), refunded_at timestamptz);
create table sale_items (id bigserial primary key, sale_id text references sales on delete cascade, product_id text references products, name text, category text, is_custom boolean not null default false, qty int not null, price numeric(10,2), cost numeric(10,2), discount_type text, discount_value numeric(10,2), discount numeric(10,2), net numeric(10,2));  -- product_id is null for custom items
create table held_sales (id text primary key, t timestamptz not null default now(), outlet_id text references outlets, cashier_id text references users, customer_id text references customers, lines jsonb not null);
create table purchases (id text primary key, number int unique not null, t timestamptz not null default now(), invoice_date date not null, outlet_id text references outlets, supplier text not null, invoice_no text not null, received_by text references users, notes text, total numeric(12,2));
create table purchase_items (id bigserial primary key, purchase_id text references purchases on delete cascade, product_id text references products, qty int not null check (qty > 0), unit_cost numeric(10,2), retail numeric(10,2), wholesale numeric(10,2));
create table quotes (id text primary key, number int unique not null, t timestamptz not null default now(), outlet_id text references outlets, created_by text references users, customer_id text references customers, valid_until date, notes text, total numeric(10,2), status text not null default 'Open' check (status in ('Open','Accepted','Declined','Converted')));
create table quote_items (id bigserial primary key, quote_id text references quotes on delete cascade, product_id text references products, name text, qty int, price numeric(10,2), discount numeric(10,2), net numeric(10,2));
create table special_orders (id text primary key, number int unique not null, t timestamptz not null default now(), outlet_id text references outlets, created_by text references users, customer_id text not null references customers, expected_date date, notes text, total numeric(10,2), status text not null default 'Ordered' check (status in ('Ordered','Ready','Completed','Cancelled')), sale_id text references sales);
create table special_order_items (id bigserial primary key, order_id text references special_orders on delete cascade, product_id text references products, name text, qty int, price numeric(10,2), discount numeric(10,2), net numeric(10,2));
create table order_payments (id text primary key, order_id text references special_orders on delete cascade, t timestamptz not null default now(), type text check (type in ('deposit','refund')), method text, amount numeric(10,2), outlet_id text references outlets, user_id text references users);
create table activity_log (id text primary key, t timestamptz not null default now(), user_id text references users, outlet_id text references outlets, type text not null, detail text);
create index on sales (outlet_id, t); create index on sale_items (sale_id); create index on activity_log (t); create index on purchases (outlet_id, invoice_date);
